// machines/plaits: VA's mixing loops (engines/va.c, va_render), hand-written SISD kernels.
// Generated by lib/gen_va_mix_kernel.py; do not edit by hand.
//
// va_aux_kernel(float *aux, const float *out, int size): aux[i] = (aux[i] - out[i]) * 0.5f.
// va_out_kernel(float *out, const float *temp, float *g, int size): g = {saw value, saw increment, square value, square
//   increment}; out[i] = out[i] * (saw += saw increment) + (square += square increment) * temp[i]; the two values go
//   back to g[0] and g[2]. Both bit-identical to selcc's code of the C loops (-DPL_VA_C).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (I0, I1, M6, L0, L1, L4
// pushed through R0, M6 = 1 and L0 = L1 = L4 = 0 set here). No SIMD.

.SECTION/PM seg_pmco;
.GLOBAL va_aux_kernel.;
.GLOBAL va_out_kernel.;
.COMPRESS;

va_aux_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I0 = R4;                                            // aux
    I1 = R8;                                            // out
    R2 = 0x3F000000;                                    // 0.5f
    R0 = 0;
    COMP(R12, R0);
    IF LE JUMP _vak_done;
    LCNTR = R12, DO _vak_e UNTIL LCE;
    R0 = DM(I0, M5);
    R1 = DM(I1, M6);
    F0 = F0 - F1;                                       // (aux[i] - out[i]) * 0.5f
    F0 = F0 * F2;
_vak_e:
    DM(I0, M6) = R0;
_vak_done:
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
va_out_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I0 = R4;                                            // out
    I1 = R8;                                            // temp
    I4 = R12;                                           // g
    R3 = DM(0, I4);                                     // saw value
    R4 = DM(1, I4);                                     // saw increment
    R5 = DM(2, I4);                                     // square value
    R6 = DM(3, I4);                                     // square increment
    R8 = DM(1, I6);                                     // size
    R0 = 0;
    COMP(R8, R0);
    IF LE JUMP _vok_done;
    LCNTR = R8, DO _vok_e UNTIL LCE;
    R0 = DM(I0, M5);
    F3 = F3 + F4;                                       // saw_gain_modulation.Next()
    F0 = F0 * F3;                                       // out[i] * saw
    R1 = DM(I1, M6);
    F5 = F5 + F6;                                       // square_gain_modulation.Next()
    F1 = F5 * F1;                                       // square * temp[i]
    F0 = F0 + F1;
_vok_e:
    DM(I0, M6) = R0;
    DM(0, I4) = R3;
    DM(2, I4) = R5;
_vok_done:
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
